import sys

class Scan:
    def __init__(self, x=None):
        if x is None:
            self.lines = sys.stdin.read().splitlines()
        else:
            self.lines = x.splitlines()
        self.index = 0
        self.tokens = []

    def next(self):
        while not self.tokens:
            if self.index >= len(self.lines):
                return None
            self.tokens = self.lines[self.index].split()
            self.index += 1
        return self.tokens.pop(0)

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())

    def nextDouble(self):
        return float(self.next())

    def nextLine(self):
        if self.index >= len(self.lines):
            return ''
        line = self.lines[self.index]
        self.index += 1
        return line

MOD = 998244353
asz = 200005

def BigMod(a, b, m):
    result = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        a = (a * a) % m
        b //= 2
    return result

f = [0] * asz

def C(n, k):
    if k > n:
        return 0
    return f[n] * BigMod(f[k], MOD - 2, MOD) % MOD * BigMod(f[n - k], MOD - 2, MOD) % MOD

def solve(n, k):
    ans = 0
    for i in range(n - k + 1):
        if i % 2 == 0:
            ans = (ans + C(n - k, i) * BigMod(n - k - i, n, MOD)) % MOD
        else:
            ans = (ans - C(n - k, i) * BigMod(n - k - i, n, MOD)) % MOD
    return ans

